static final ThreadLocal<RequestContext> CURRENT =
        ThreadLocal.withInitial(RequestContext::new);

void handle(Request request) {
    CURRENT.set(RequestContext.forRequest(request));   // this thread's copy
    try {
        service.invoke(request);                       // reads CURRENT.get() deep below
    } finally {
        CURRENT.remove();                              // pooled thread: never leak
    }
}

